<template>
  <div class="version-page">
    <header class="version-hero">
      <div>
        <p class="eyebrow">PRODUCT UPDATES</p>
        <h1>版本資訊</h1>
        <p>查看 iFarmer 的功能更新、作業調整與問題修正紀錄。</p>
      </div>
      <div class="current-version">
        <small>CURRENT VERSION</small>
        <strong>{{ releases[0].version }}</strong>
        <span><i class="fa fa-check-circle"></i> 目前版本</span>
      </div>
    </header>

    <div class="summary-bar">
      <div><span class="summary-icon"><i class="fa fa-code-fork"></i></span><p><small>版本紀錄</small><strong>{{ releases.length }} 個版本</strong></p></div>
      <div><span class="summary-icon"><i class="fa fa-calendar-check-o"></i></span><p><small>最近更新</small><strong>{{ releases[0].date }}</strong></p></div>
      <div><span class="summary-icon"><i class="fa fa-list-ul"></i></span><p><small>更新項目</small><strong>{{ totalUpdates }} 項</strong></p></div>
    </div>

    <section class="release-section" aria-labelledby="history-title">
      <div class="section-heading">
        <div><span>RELEASE NOTES</span><h2 id="history-title">更新紀錄</h2></div>
        <p>點選版本即可查看完整內容</p>
      </div>

      <div class="release-list">
        <article v-for="(release, index) in releases" :key="release.version" class="release-card" :class="{ open: isOpen(release.version) }">
          <button class="release-trigger" type="button" :aria-expanded="isOpen(release.version)" @click="toggle(release.version)">
            <span class="timeline-marker"><i :class="index === 0 ? 'fa fa-check' : 'fa fa-tag'"></i></span>
            <span class="release-meta">
              <span class="version-row"><strong>{{ release.version }}</strong><em v-if="index === 0">最新</em></span>
              <small>發布日期 {{ release.date }}</small>
            </span>
            <span class="update-count">{{ countItems(release) }} 項更新</span>
            <i class="toggle-icon fa fa-angle-down"></i>
          </button>

          <transition name="slide">
            <div v-show="isOpen(release.version)" class="release-content">
              <section v-for="section in release.sections" :key="section.title" class="change-group">
                <h3>{{ section.title }}</h3>
                <div v-for="item in section.items" :key="item.title" class="change-item">
                  <span class="change-dot"></span>
                  <div>
                    <h4>{{ item.title }}</h4>
                    <ul v-if="item.details && item.details.length">
                      <li v-for="detail in item.details" :key="detail">{{ detail }}</li>
                    </ul>
                  </div>
                </div>
              </section>
            </div>
          </transition>
        </article>
      </div>
    </section>

    <footer class="support-note"><i class="fa fa-question-circle-o"></i><span>若更新後遇到操作問題，請聯絡系統管理員。</span></footer>
  </div>
</template>

<script>
export default {
  name: 'Version',
  data() {
    return {
      openVersions: ['V2.1.0003'],
      releases: [
        {
          version: 'V2.1.0003', date: '2018/12/19',
          sections: [
            {
              title: '報表優化',
              items: [
                { title: 'RP020209 母豬分娩斷奶情況分析', details: ['修正查詢欄位判斷'] },
                { title: 'RP020210 生產日報表', details: ['修改時間區間查詢判斷', 'WebAPI 轉換至 V2'] }
              ]
            },
            {
              title: '作業流程調整',
              items: [
                { title: '專業用藥調整', details: ['調整專業用藥可選取的專業診療單內容及相關檔案'] },
                { title: '仔豬移欄作業', details: ['移出時將 SwineState 變更為保育豬'] },
                { title: '移欄狀態變更', details: ['待產移轉、仔豬轉保育改為移出時變更狀態'] },
                { title: '移欄歷程優化', details: ['其餘未變更豬隻狀態的移欄作業，不產生 SwineStatusChangeHistory'] }
              ]
            }
          ]
        },
        {
          version: 'V2.1.0001', date: '2018/12/04',
          sections: [
            {
              title: '新增功能',
              items: [
                { title: '批量舍資料維護', details: ['可批量建立舍欄，快速完成新增棟舍作業'] },
                { title: '批量欄資料維護', details: ['可批量建立舍欄，快速新增欄位'] },
                { title: '批量死淘作業', details: ['新增銷售選項，可透過批量死淘功能執行商品豬銷售'] },
                { title: '新增報表', details: ['位置豬隻存欄明細表', '料塔耗用明細表', '群體餵飼紀錄明細表', '個體餵飼紀錄明細表'] }
              ]
            },
            {
              title: '功能修正',
              items: [
                { title: '修正仔豬批號規則', details: ['依分娩棟舍序號進行批號區分', '新增棟舍維護時，依 LocationTypeCode 寫入分娩棟舍序號'] }
              ]
            }
          ]
        }
      ]
    }
  },
  computed: {
    totalUpdates() {
      return this.releases.reduce((total, release) => total + this.countItems(release), 0)
    }
  },
  methods: {
    countItems(release) {
      return release.sections.reduce((total, section) => total + section.items.length, 0)
    },
    isOpen(version) {
      return this.openVersions.indexOf(version) > -1
    },
    toggle(version) {
      const index = this.openVersions.indexOf(version)
      if (index > -1) this.openVersions.splice(index, 1)
      else this.openVersions.push(version)
    }
  }
}
</script>

<style scoped>
.version-page,.version-page *{box-sizing:border-box}.version-page{--forest:#173f35;--green:#2d715c;--lime:#b9d96b;--ink:#17221f;padding:8px 4px 34px;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans TC",sans-serif}.version-hero{position:relative;display:flex;align-items:center;justify-content:space-between;min-height:175px;padding:32px 39px;overflow:hidden;border-radius:20px;color:#fff;background:linear-gradient(125deg,#173f35,#28624f);box-shadow:0 14px 35px rgba(23,63,53,.15)}.version-hero:after{content:'';position:absolute;width:250px;height:250px;right:-110px;top:-120px;border:45px solid rgba(185,217,107,.09);border-radius:50%}.eyebrow{margin:0 0 8px;color:var(--lime);font-size:10px;font-weight:700;letter-spacing:.16em}.version-hero h1{margin:0 0 9px;font-size:30px;letter-spacing:-.03em}.version-hero>div:first-child>p:last-child{margin:0;color:rgba(255,255,255,.7);font-size:13px}.current-version{position:relative;z-index:1;display:grid;min-width:175px;padding:17px 19px;border:1px solid rgba(255,255,255,.13);border-radius:14px;background:rgba(255,255,255,.07);backdrop-filter:blur(5px)}.current-version small{color:rgba(255,255,255,.45);font-size:8px;font-weight:700;letter-spacing:.12em}.current-version strong{margin:3px 0 7px;font-size:20px}.current-version span{color:var(--lime);font-size:10px}.current-version i{margin-right:5px}.summary-bar{display:grid;grid-template-columns:repeat(3,1fr);margin:18px 0 29px;border:1px solid #e2eae6;border-radius:15px;background:#fff;box-shadow:0 5px 18px rgba(28,57,48,.04)}.summary-bar>div{display:flex;align-items:center;justify-content:center;gap:11px;margin:13px 0;padding:6px 20px;border-right:1px solid #edf1ef}.summary-bar>div:last-child{border-right:0}.summary-icon{display:grid;place-items:center;width:35px;height:35px;border-radius:10px;color:var(--green);background:#edf5f1;font-size:13px}.summary-bar p{margin:0}.summary-bar small{display:block;color:#92a09b;font-size:9px}.summary-bar strong{display:block;margin-top:2px;color:#30423b;font-size:12px}.section-heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:14px;padding:0 3px}.section-heading span{display:block;color:#789087;font-size:9px;font-weight:700;letter-spacing:.14em}.section-heading h2{margin:3px 0 0;font-size:21px}.section-heading p{margin:0;color:#8a9792;font-size:10px}.release-list{display:grid;gap:11px}.release-card{overflow:hidden;border:1px solid #e1e9e5;border-radius:15px;background:#fff;box-shadow:0 5px 18px rgba(28,57,48,.04)}.release-card.open{border-color:#cbdcd4}.release-trigger{display:grid;grid-template-columns:42px 1fr auto 30px;align-items:center;width:100%;padding:15px 18px;border:0;color:inherit;background:#fff;text-align:left;cursor:pointer}.timeline-marker{display:grid;place-items:center;width:31px;height:31px;border-radius:10px;color:#71847c;background:#edf2ef;font-size:11px}.open .timeline-marker{color:var(--forest);background:var(--lime)}.release-meta{display:block}.version-row{display:flex;align-items:center;gap:8px}.version-row strong{font-size:14px}.version-row em{padding:2px 7px;border-radius:10px;color:#3f725f;background:#e8f3ed;font-size:9px;font-style:normal;font-weight:700}.release-meta small{display:block;margin-top:3px;color:#95a19d;font-size:9px}.update-count{padding:5px 9px;border-radius:12px;color:#70817a;background:#f3f6f4;font-size:9px;font-weight:600}.toggle-icon{margin-left:auto;color:#83928c;text-align:center;transition:.2s}.open .toggle-icon{transform:rotate(180deg)}.release-content{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;padding:7px 24px 23px 75px;border-top:1px solid #edf1ef;background:#fbfcfb}.change-group h3{margin:15px 0 12px;color:var(--green);font-size:11px;font-weight:700;letter-spacing:.06em}.change-item{display:flex;align-items:flex-start;gap:10px;margin-top:12px}.change-dot{flex:0 0 6px;height:6px;margin-top:5px;border-radius:50%;background:var(--lime);box-shadow:0 0 0 3px #eef5dc}.change-item h4{margin:0;color:#3d5048;font-size:11px;line-height:1.5}.change-item ul{margin:5px 0 0;padding:0;list-style:none}.change-item li{position:relative;margin-top:3px;padding-left:11px;color:#7b8984;font-size:10px;line-height:1.55}.change-item li:before{content:'—';position:absolute;left:0;color:#a3afaa}.slide-enter-active,.slide-leave-active{transition:opacity .18s}.slide-enter,.slide-leave-to{opacity:0}.support-note{display:flex;align-items:center;justify-content:center;gap:7px;margin-top:18px;color:#83918c;font-size:10px}.support-note i{color:var(--green)}
@media(max-width:720px){.version-hero{padding:28px 25px}.current-version{display:none}.summary-bar{grid-template-columns:1fr}.summary-bar>div{justify-content:flex-start;margin:0 14px;padding:12px 8px;border-right:0;border-bottom:1px solid #edf1ef}.summary-bar>div:last-child{border-bottom:0}.release-content{grid-template-columns:1fr;padding:6px 20px 22px 61px}.section-heading p{display:none}}
@media(max-width:460px){.version-hero{min-height:155px;border-radius:15px}.version-hero h1{font-size:25px}.version-hero>div:first-child>p:last-child{line-height:1.6}.release-trigger{grid-template-columns:38px 1fr 24px;padding:14px 12px}.update-count{display:none}.release-content{padding-left:20px}}
</style>



