<template>
  <main class="login-page">
    <div class="ambient ambient-one"></div>
    <div class="ambient ambient-two"></div>
    <section class="login-shell" aria-label="iFarmer 登入">
      <aside class="brand-panel">
        <div class="brand-mark" aria-hidden="true"><i class="fa fa-leaf"></i></div>
        <div class="brand-copy">
          <p class="eyebrow">SMART FARM MANAGEMENT</p>
          <h1>讓每一筆農場資料，<br>都成為更好的決策。</h1>
          <p class="brand-description">整合生產、營運與現場資訊，以即時數據協助團隊掌握農場狀況。</p>
        </div>
        <div class="feature-list" aria-label="系統特色">
          <span><i class="fa fa-check"></i> 即時營運資訊</span>
          <span><i class="fa fa-check"></i> 集中化農場管理</span>
          <span><i class="fa fa-check"></i> 安全權限控管</span>
        </div>
        <p class="copyright">iFarmer 智慧農場管理平台</p>
      </aside>

      <section class="form-panel">
        <div class="form-wrap">
          <div class="mobile-brand"><span class="mini-mark"><i class="fa fa-leaf"></i></span><span>iFarmer</span></div>
          <header class="form-header">
            <p class="welcome">歡迎回來</p>
            <h2>登入管理平台</h2>
            <p>請輸入您的帳號與密碼以繼續</p>
          </header>

          <form @submit.prevent="login" novalidate>
            <label class="field-label" for="Account">使用者帳號</label>
            <div class="field" :class="{ 'has-error': submitted && !accountNo }">
              <i class="fa fa-user-o field-icon" aria-hidden="true"></i>
              <input id="Account" ref="accountInput" v-model.trim="accountNo" type="text" autocomplete="username" placeholder="請輸入帳號" aria-label="使用者帳號">
            </div>

            <div class="password-row">
              <label class="field-label" for="Password">密碼</label>
              <router-link to="/ForgotPassword">修改密碼</router-link>
            </div>
            <div class="field" :class="{ 'has-error': submitted && !password }">
              <i class="fa fa-lock field-icon" aria-hidden="true"></i>
              <input id="Password" v-model="password" :type="showPassword ? 'text' : 'password'" autocomplete="current-password" placeholder="請輸入密碼" aria-label="密碼">
              <button class="visibility-button" type="button" :aria-label="showPassword ? '隱藏密碼' : '顯示密碼'" @click="showPassword = !showPassword">
                <i :class="showPassword ? 'fa fa-eye-slash' : 'fa fa-eye'"></i>
              </button>
            </div>

            <p v-if="errorMessage" class="error-message" role="alert"><i class="fa fa-exclamation-circle"></i>{{ errorMessage }}</p>
            <button id="LoginBtn" class="login-button" type="submit" :disabled="isLoading">
              <i v-if="isLoading" class="fa fa-circle-o-notch fa-spin"></i>
              <span>{{ isLoading ? '登入中…' : '登入系統' }}</span>
              <i v-if="!isLoading" class="fa fa-arrow-right"></i>
            </button>
          </form>

          <div class="demo-card">
            <div class="demo-heading">
              <span><i class="fa fa-flask"></i> Demo 測試帳號</span>
              <button type="button" @click="fillDemoCredentials">一鍵帶入</button>
            </div>
            <div class="credential-grid">
              <div><small>帳號</small><strong>{{ demoAccountNo }}</strong></div>
              <div><small>密碼</small><strong>{{ demoPassword }}</strong></div>
            </div>
            <p>此為前端展示資料，修改密碼後會儲存在此瀏覽器。</p>
          </div>
        </div>
      </section>
    </section>
  </main>
</template>

<script>
import { loading } from '@/assets/js/iFarmer/library/commonLib'
import { isAuthenticated, isAuthenticatedByToken, getDemoCredentials } from '@/assets/js/iFarmer/manager/authManager'
import Cookies from 'js-cookie'
import { expireCookieKey } from '@/assets/js/iFarmer/manager/configManager'

export default {
  name: 'Login',
  data() {
    const demo = getDemoCredentials()
    return {
      accountNo: '', password: '', demoAccountNo: demo.accountNo, demoPassword: demo.password,
      showPassword: false, submitted: false, isLoading: false, errorMessage: ''
    }
  },
  mounted() {
    if (Cookies.get(expireCookieKey)) {
      Cookies.remove(expireCookieKey)
      this.errorMessage = '連線已逾時，請重新登入。'
    }
    const token = new URL(window.location.href).searchParams.get('t')
    if (token) {
      const loadingInst = loading()
      isAuthenticatedByToken(token, result => {
        loadingInst.close()
        if (result) window.location = window.location.href.split('?')[0]
      })
    }
    this.$nextTick(() => this.$refs.accountInput.focus())
  },
  activated() {
    this.demoPassword = getDemoCredentials().password
  },
  methods: {
    fillDemoCredentials() {
      this.accountNo = this.demoAccountNo
      this.password = this.demoPassword
      this.errorMessage = ''
    },
    login() {
      this.submitted = true
      this.errorMessage = ''
      if (!this.accountNo || !this.password) {
        this.errorMessage = '請輸入帳號與密碼。'
        return
      }
      this.isLoading = true
      isAuthenticated(this.accountNo, this.password, result => {
        this.isLoading = false
        if (result) {
          location.reload()
          return
        }
        this.errorMessage = '帳號或密碼不正確，請確認後再試一次。'
      })
    }
  }
}
</script>

<style scoped>
.login-page, .login-page * { box-sizing:border-box; }
.login-page { --forest:#173f35; --green:#2d715c; --lime:#b9d96b; --ink:#17221f; position:fixed; z-index:2000; inset:0; display:flex; align-items:center; justify-content:center; overflow:auto; padding:36px; color:var(--ink); background:#eef3ef; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans TC",sans-serif; }
.ambient { position:absolute; border-radius:50%; filter:blur(2px); opacity:.6; }
.ambient-one { width:420px; height:420px; top:-210px; right:-90px; background:#d8e8b9; }
.ambient-two { width:300px; height:300px; bottom:-180px; left:-80px; background:#c4ded2; }
.login-shell { position:relative; display:grid; grid-template-columns:minmax(360px,.9fr) minmax(460px,1.1fr); width:min(1080px,100%); min-height:680px; overflow:hidden; border:1px solid rgba(23,63,53,.08); border-radius:28px; background:white; box-shadow:0 30px 80px rgba(25,58,48,.14); }
.brand-panel { position:relative; display:flex; flex-direction:column; padding:58px 54px 42px; overflow:hidden; color:white; background:linear-gradient(145deg,#214e40,#12362f 72%); }
.brand-panel::before,.brand-panel::after { content:''; position:absolute; border:1px solid rgba(255,255,255,.09); border-radius:50%; }
.brand-panel::before { width:440px; height:440px; right:-260px; bottom:-80px; }
.brand-panel::after { width:280px; height:280px; right:-150px; bottom:0; }
.brand-mark { display:grid; place-items:center; width:52px; height:52px; margin-bottom:88px; border-radius:16px; color:var(--forest); background:var(--lime); font-size:24px; transform:rotate(-4deg); }
.eyebrow { margin:0 0 17px; color:var(--lime); font-size:11px; font-weight:700; letter-spacing:.18em; }
.brand-copy h1 { margin:0; font-size:35px; line-height:1.45; letter-spacing:-.035em; font-weight:700; }
.brand-description { max-width:340px; margin:22px 0 0; color:rgba(255,255,255,.68); font-size:15px; line-height:1.8; }
.feature-list { display:grid; gap:13px; margin-top:42px; color:rgba(255,255,255,.82); font-size:13px; }
.feature-list i { display:inline-grid; place-items:center; width:20px; height:20px; margin-right:9px; border-radius:50%; color:var(--forest); background:var(--lime); font-size:9px; }
.copyright { position:relative; z-index:1; margin:auto 0 0; color:rgba(255,255,255,.42); font-size:12px; }
.form-panel { display:flex; align-items:center; justify-content:center; padding:54px 70px; background:#fff; }
.form-wrap { width:100%; max-width:410px; }
.mobile-brand { display:none; align-items:center; gap:10px; margin-bottom:34px; color:var(--forest); font-size:20px; font-weight:700; }
.mini-mark { display:inline-grid; place-items:center; width:34px; height:34px; border-radius:10px; color:var(--forest); background:var(--lime); font-size:15px; }
.form-header { margin-bottom:32px; }
.form-header .welcome { margin:0 0 8px; color:var(--green); font-size:13px; font-weight:700; letter-spacing:.08em; }
.form-header h2 { margin:0 0 10px; color:var(--ink); font-size:30px; letter-spacing:-.03em; }
.form-header > p:last-child { margin:0; color:#7b8884; font-size:14px; }
.field-label { display:block; margin:0 0 9px; color:#384640; font-size:13px; font-weight:600; line-height: 2;}
.password-row { display:flex; align-items:center; justify-content:space-between; margin-top:20px; }
.password-row .field-label { margin-bottom:9px; }
.password-row a { margin-bottom:9px; color:var(--green); font-size:12px; font-weight:600; text-decoration:none; }
.field { position:relative; display:flex; align-items:center; height:50px; border:1px solid #dfe7e3; border-radius:12px; background:#fbfcfb; transition:.2s; }
.field:focus-within { border-color:var(--green); background:white; box-shadow:0 0 0 3px rgba(45,113,92,.1); }
.field.has-error { border-color:#cf5d58; }
.field-icon { width:47px; color:#8a9792; text-align:center; }
.field input { flex:1; min-width:0; height:100%; padding:0 12px 0 0; border:0; outline:0; color:var(--ink); background:transparent; font:inherit; font-size:14px; }
.field input::placeholder { color:#a6b0ac; }
.visibility-button { width:46px; height:100%; border:0; color:#7d8d87; background:transparent; cursor:pointer; }
.error-message { margin:14px 0 0; color:#bd4945; font-size:12px; }
.error-message i { margin-right:7px; }
.login-button { display:flex; align-items:center; justify-content:center; gap:12px; width:100%; height:52px; margin-top:24px; border:0; border-radius:12px; color:white; background:var(--forest); font-size:14px; font-weight:700; cursor:pointer; transition:.2s; }
.login-button:hover { background:#235c4b; transform:translateY(-1px); box-shadow:0 9px 20px rgba(23,63,53,.18); }
.login-button:disabled { opacity:.65; cursor:wait; transform:none; }
.login-button .fa-arrow-right { margin-left:auto; margin-right:17px; }
.demo-card { margin-top:25px; padding:16px 18px 14px; border:1px dashed #b9cfc5; border-radius:13px; background:#f5f9f6; }
.demo-heading { display:flex; align-items:center; justify-content:space-between; margin-bottom:13px; color:#416057; font-size:12px; font-weight:700; }
.demo-heading i { margin-right:6px; color:var(--green); }
.demo-heading button { border:0; padding:0; color:var(--green); background:transparent; font-size:12px; font-weight:700; cursor:pointer; }
.credential-grid { display:grid; grid-template-columns:1fr 1fr; gap:8px; }
.credential-grid div { padding:9px 11px; border-radius:8px; background:white; }
.credential-grid small { display:block; margin-bottom:3px; color:#84918c; font-size:10px; }
.credential-grid strong { color:#2c3e38; font-family:ui-monospace,SFMono-Regular,Menlo,monospace; font-size:12px; }
.demo-card > p { margin:10px 0 0; color:#82908b; font-size:10px; }
@media (max-width:900px) { .login-page{padding:22px}.login-shell{grid-template-columns:1fr;width:min(560px,100%);min-height:auto}.brand-panel{display:none}.form-panel{padding:46px 56px}.mobile-brand{display:flex} }
@media (max-width:520px) { .login-page{align-items:flex-start;padding:0;background:white}.login-shell{min-height:100%;border:0;border-radius:0;box-shadow:none}.form-panel{align-items:flex-start;padding:32px 24px 38px}.form-header h2{font-size:27px}.credential-grid{grid-template-columns:1fr} }
</style>



