<template>
  <div class="unauthorized-page">
    <section class="error-card">
      <div class="visual-panel" aria-hidden="true">
        <div class="lock-orbit"><span class="lock"><i class="fa fa-lock"></i></span></div>
        <span class="error-code">401</span>
      </div>
      <div class="message-panel">
        <p class="eyebrow">ACCESS RESTRICTED</p>
        <h1>您沒有瀏覽此頁面的權限</h1>
        <p class="description">目前登入的帳號未被授權使用這項功能。您可以返回上一頁，或回到作業總覽繼續操作。</p>
        <div class="notice"><i class="fa fa-info-circle"></i><span>如需開通權限，請聯絡系統管理員協助設定。</span></div>
        <div class="actions">
          <button type="button" class="secondary" @click="goBack"><i class="fa fa-arrow-left"></i>返回上一頁</button>
          <button type="button" class="primary" @click="goHome">回到作業總覽<i class="fa fa-home"></i></button>
        </div>
      </div>
    </section>
  </div>
</template>

<script>
export default {
  name: 'UnAuthorize',
  methods: {
    goBack() {
      if (window.history.length > 1) this.$router.go(-1)
      else this.goHome()
    },
    goHome() {
      this.$router.push({ name: 'SiteMap' })
    }
  }
}
</script>

<style scoped>
.unauthorized-page,.unauthorized-page *{box-sizing:border-box}.unauthorized-page{--forest:#173f35;--green:#2d715c;--lime:#b9d96b;display:flex;align-items:center;justify-content:center;min-height:calc(100vh - 175px);padding:32px 10px;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans TC",sans-serif}.error-card{display:grid;grid-template-columns:340px minmax(380px,1fr);width:min(850px,100%);min-height:430px;overflow:hidden;border:1px solid #e1e9e5;border-radius:22px;background:#fff;box-shadow:0 18px 50px rgba(23,63,53,.09)}.visual-panel{position:relative;display:flex;align-items:center;justify-content:center;overflow:hidden;color:#fff;background:linear-gradient(145deg,#214e40,#12362f)}.visual-panel:before,.visual-panel:after{content:'';position:absolute;border:1px solid rgba(255,255,255,.09);border-radius:50%}.visual-panel:before{width:310px;height:310px;left:-175px;top:-115px}.visual-panel:after{width:230px;height:230px;right:-130px;bottom:-70px}.lock-orbit{position:relative;display:grid;place-items:center;width:135px;height:135px;border:1px solid rgba(185,217,107,.26);border-radius:50%}.lock-orbit:before{content:'';position:absolute;width:97px;height:97px;border:1px dashed rgba(255,255,255,.2);border-radius:50%}.lock{position:relative;z-index:1;display:grid;place-items:center;width:60px;height:60px;border-radius:19px;color:var(--forest);background:var(--lime);font-size:24px;box-shadow:0 12px 25px rgba(0,0,0,.16)}.error-code{position:absolute;left:27px;bottom:20px;color:rgba(255,255,255,.12);font-size:80px;font-weight:800;letter-spacing:-.07em}.message-panel{display:flex;flex-direction:column;justify-content:center;padding:58px 60px}.eyebrow{margin:0 0 12px;color:var(--green);font-size:10px;font-weight:700;letter-spacing:.16em}.message-panel h1{max-width:380px;margin:0 0 17px;color:#18231f;font-size:29px;line-height:1.4;letter-spacing:-.03em}.description{max-width:420px;margin:0;color:#73817c;font-size:13px;line-height:1.8}.notice{display:flex;align-items:flex-start;gap:9px;margin-top:24px;padding:13px 14px;border-radius:10px;color:#62736c;background:#f2f7f4;font-size:11px;line-height:1.55}.notice i{margin-top:2px;color:var(--green)}.actions{display:flex;gap:10px;margin-top:27px}.actions button{height:44px;padding:0 18px;border-radius:10px;font-size:12px;font-weight:700;cursor:pointer;transition:.2s}.actions button i{margin:0 7px}.secondary{border:1px solid #dce5e1;color:#4f625a;background:#fff}.secondary:hover{border-color:#aebfb7;background:#fafcfb}.primary{border:1px solid var(--forest);color:#fff;background:var(--forest)}.primary:hover{background:#275f4e;box-shadow:0 8px 18px rgba(23,63,53,.15)}
@media(max-width:760px){.unauthorized-page{min-height:auto;padding:15px 0}.error-card{grid-template-columns:1fr}.visual-panel{min-height:190px}.lock-orbit{width:110px;height:110px}.error-code{font-size:62px}.message-panel{padding:38px 34px}.message-panel h1{font-size:24px}}
@media(max-width:430px){.message-panel{padding:32px 23px}.actions{flex-direction:column}.actions button{width:100%}}
</style>



