<template>
  <main class="password-page">
    <section class="password-shell">
      <aside class="security-panel">
        <router-link class="brand" to="/"><span><i class="fa fa-leaf"></i></span>iFarmer</router-link>
        <div class="security-copy">
          <div class="shield"><i class="fa fa-shield"></i></div>
          <p class="eyebrow">ACCOUNT SECURITY</p>
          <h1>定期更新密碼，<br>守護農場重要資料。</h1>
          <p>請使用至少 8 個字元，並混合英文字母與數字，提高帳號安全性。</p>
        </div>
        <div class="security-tip"><i class="fa fa-lightbulb-o"></i><span>Demo 密碼只會儲存在目前瀏覽器，不會上傳到伺服器。</span></div>
      </aside>

      <section class="form-panel">
        <div class="form-wrap">
          <button class="back-button" type="button" @click="cancel"><i class="fa fa-arrow-left"></i> 返回登入</button>
          <header>
            <p class="step">帳號安全</p>
            <h2>修改密碼</h2>
            <p>輸入目前密碼，並設定一組新的登入密碼。</p>
          </header>

          <form @submit.prevent="resetPwd" novalidate>
            <label for="userID">使用者帳號</label>
            <div class="field" :class="{ invalid: submitted && !userID }">
              <i class="fa fa-user-o"></i>
              <input id="userID" v-model.trim="userID" type="text" autocomplete="username" placeholder="請輸入帳號">
            </div>

            <label for="oldPwd">目前密碼</label>
            <div class="field" :class="{ invalid: submitted && !oldPwd }">
              <i class="fa fa-lock"></i>
              <input id="oldPwd" v-model="oldPwd" :type="showPasswords ? 'text' : 'password'" autocomplete="current-password" placeholder="請輸入目前密碼">
            </div>

            <label for="newPwd">新密碼</label>
            <div class="field" :class="{ invalid: submitted && newPwd.length < 8 }">
              <i class="fa fa-key"></i>
              <input id="newPwd" v-model="newPwd" :type="showPasswords ? 'text' : 'password'" autocomplete="new-password" placeholder="至少 8 個字元">
              <button type="button" :aria-label="showPasswords ? '隱藏密碼' : '顯示密碼'" @click="showPasswords = !showPasswords"><i :class="showPasswords ? 'fa fa-eye-slash' : 'fa fa-eye'"></i></button>
            </div>

            <div class="strength" aria-label="密碼強度">
              <span :class="{ active: strength >= 1 }"></span><span :class="{ active: strength >= 2 }"></span><span :class="{ active: strength >= 3 }"></span>
              <small>{{ strengthText }}</small>
            </div>

            <label for="newPwdConfirmed">確認新密碼</label>
            <div class="field" :class="{ invalid: submitted && newPwdConfirmed !== newPwd }">
              <i class="fa fa-check-circle-o"></i>
              <input id="newPwdConfirmed" v-model="newPwdConfirmed" :type="showPasswords ? 'text' : 'password'" autocomplete="new-password" placeholder="請再次輸入新密碼">
            </div>

            <p v-if="errorMessage" class="error-message" role="alert"><i class="fa fa-exclamation-circle"></i>{{ errorMessage }}</p>
            <button class="submit-button" type="submit" :disabled="isSubmitting">
              <i v-if="isSubmitting" class="fa fa-circle-o-notch fa-spin"></i>{{ isSubmitting ? '更新中…' : '確認修改密碼' }}
            </button>
          </form>

          <div class="demo-hint"><span>Demo 帳號</span><strong>{{ demoAccountNo }}</strong><span>目前密碼</span><strong>{{ demoPassword }}</strong></div>
        </div>
      </section>
    </section>
  </main>
</template>

<script>
import { changePassword, getDemoCredentials } from '@/assets/js/iFarmer/manager/authManager'

export default {
  name: 'ForgotPassword',
  data() {
    const demo = getDemoCredentials()
    return {
      userID: demo.accountNo, oldPwd: '', newPwd: '', newPwdConfirmed: '',
      demoAccountNo: demo.accountNo, demoPassword: demo.password,
      showPasswords: false, submitted: false, isSubmitting: false, errorMessage: ''
    }
  },
  computed: {
    strength() {
      if (!this.newPwd) return 0
      let value = this.newPwd.length >= 8 ? 1 : 0
      if (/[A-Za-z]/.test(this.newPwd) && /[0-9]/.test(this.newPwd)) value++
      if (/[^A-Za-z0-9]/.test(this.newPwd) && this.newPwd.length >= 10) value++
      return Math.min(value, 3)
    },
    strengthText() {
      return ['尚未輸入', '基本', '良好', '安全'][this.strength]
    }
  },
  activated() {
    const demo = getDemoCredentials()
    this.demoPassword = demo.password
    if (!this.userID) this.userID = demo.accountNo
  },
  methods: {
    resetPwd() {
      this.submitted = true
      this.errorMessage = ''
      if (!this.userID || !this.oldPwd || !this.newPwd || !this.newPwdConfirmed) {
        this.errorMessage = '請完整填寫所有欄位。'
        return
      }
      if (this.newPwd.length < 8 || !/[A-Za-z]/.test(this.newPwd) || !/[0-9]/.test(this.newPwd)) {
        this.errorMessage = '新密碼需至少 8 個字元，並包含英文字母與數字。'
        return
      }
      if (this.newPwd !== this.newPwdConfirmed) {
        this.errorMessage = '兩次輸入的新密碼不一致。'
        return
      }
      if (this.oldPwd === this.newPwd) {
        this.errorMessage = '新密碼不可與目前密碼相同。'
        return
      }

      this.isSubmitting = true
      changePassword(this.userID, this.oldPwd, this.newPwd, result => {
        this.isSubmitting = false
        if (result === true) {
          this.$notify.success({ title: '密碼更新成功', message: '請使用新密碼重新登入。' })
          this.oldPwd = this.newPwd = this.newPwdConfirmed = ''
          this.submitted = false
          this.$router.push({ name: 'Login' })
          return
        }
        this.errorMessage = '帳號或目前密碼不正確，請重新確認。'
      })
    },
    cancel() {
      this.errorMessage = ''
      this.$router.push({ name: 'Login' })
    }
  }
}
</script>

<style scoped>
.password-page, .password-page * { box-sizing:border-box; }
.password-page { --forest:#173f35; --green:#2d715c; --lime:#b9d96b; --ink:#17221f; position:fixed; z-index:2000; inset:0; display:flex; align-items:center; justify-content:center; overflow:auto; padding:36px; color:var(--ink); background:#eef3ef; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans TC",sans-serif; }
.password-shell { display:grid; grid-template-columns:minmax(330px,.85fr) minmax(490px,1.15fr); width:min(1040px,100%); min-height:690px; overflow:hidden; border:1px solid rgba(23,63,53,.08); border-radius:28px; background:white; box-shadow:0 30px 80px rgba(25,58,48,.14); }
.security-panel { position:relative; display:flex; flex-direction:column; overflow:hidden; padding:48px 50px; color:white; background:linear-gradient(150deg,#214e40,#12362f); }
.security-panel::after { content:''; position:absolute; width:380px; height:380px; right:-250px; bottom:-100px; border:70px solid rgba(185,217,107,.06); border-radius:50%; }
.brand { display:flex; align-items:center; gap:12px; color:white; font-size:20px; font-weight:700; text-decoration:none; }
.brand span { display:grid; place-items:center; width:38px; height:38px; border-radius:11px; color:var(--forest); background:var(--lime); font-size:17px; }
.security-copy { margin:auto 0; }
.shield { display:grid; place-items:center; width:62px; height:62px; margin-bottom:30px; border:1px solid rgba(255,255,255,.18); border-radius:20px; color:var(--lime); background:rgba(255,255,255,.08); font-size:27px; }
.eyebrow { margin:0 0 14px; color:var(--lime); font-size:11px; font-weight:700; letter-spacing:.16em; }
.security-copy h1 { margin:0 0 20px; font-size:31px; line-height:1.5; letter-spacing:-.03em; }
.security-copy > p:last-child { max-width:330px; margin:0; color:rgba(255,255,255,.67); font-size:14px; line-height:1.8; }
.security-tip { position:relative; z-index:1; display:flex; gap:11px; padding:14px 15px; border:1px solid rgba(255,255,255,.1); border-radius:12px; color:rgba(255,255,255,.68); background:rgba(255,255,255,.05); font-size:11px; line-height:1.6; }
.security-tip i { color:var(--lime); font-size:15px; }
.form-panel { display:flex; align-items:center; justify-content:center; padding:46px 72px; }
.form-wrap { width:100%; max-width:410px; }
.back-button { margin-bottom:28px; border:0; padding:0; color:#60716a; background:transparent; font-size:12px; font-weight:600; cursor:pointer; }
.back-button i { margin-right:8px; }
header { margin-bottom:25px; }
header .step { margin:0 0 7px; color:var(--green); font-size:12px; font-weight:700; letter-spacing:.08em; }
header h2 { margin:0 0 8px; font-size:29px; letter-spacing:-.03em; }
header > p:last-child { margin:0; color:#7b8884; font-size:13px; }
label { display:block; margin:15px 0 7px; color:#384640; font-size:12px; font-weight:600; }
.field { display:flex; align-items:center; height:46px; border:1px solid #dfe7e3; border-radius:11px; background:#fbfcfb; transition:.2s; }
.field:focus-within { border-color:var(--green); background:white; box-shadow:0 0 0 3px rgba(45,113,92,.1); }
.field.invalid { border-color:#cf5d58; }
.field > i { width:43px; color:#8a9792; text-align:center; }
.field input { flex:1; min-width:0; height:100%; padding:0 10px 0 0; border:0; outline:0; color:var(--ink); background:transparent; font:inherit; font-size:13px; }
.field input::placeholder { color:#a6b0ac; }
.field button { width:43px; height:100%; border:0; color:#7d8d87; background:transparent; cursor:pointer; }
.strength { display:grid; grid-template-columns:1fr 1fr 1fr auto; align-items:center; gap:5px; margin-top:8px; }
.strength span { height:3px; border-radius:4px; background:#e2e8e5; }
.strength span.active { background:var(--green); }
.strength small { min-width:35px; margin-left:5px; color:#82908b; font-size:10px; }
.error-message { margin:13px 0 0; color:#bd4945; font-size:12px; }
.error-message i { margin-right:7px; }
.submit-button { width:100%; height:49px; margin-top:20px; border:0; border-radius:12px; color:white; background:var(--forest); font-size:13px; font-weight:700; cursor:pointer; transition:.2s; }
.submit-button:hover { background:#235c4b; box-shadow:0 9px 20px rgba(23,63,53,.18); }
.submit-button:disabled { opacity:.65; cursor:wait; }
.submit-button i { margin-right:8px; }
.demo-hint { display:flex; align-items:center; justify-content:center; gap:7px; flex-wrap:wrap; margin-top:17px; padding:10px; border-radius:9px; color:#81908a; background:#f5f9f6; font-size:10px; }
.demo-hint strong { margin-right:7px; color:#34564b; font-family:ui-monospace,SFMono-Regular,Menlo,monospace; }
@media(max-width:850px){.password-page{padding:22px}.password-shell{grid-template-columns:1fr;width:min(560px,100%);min-height:auto}.security-panel{display:none}.form-panel{padding:42px 56px}}
@media(max-width:520px){.password-page{align-items:flex-start;padding:0;background:white}.password-shell{min-height:100%;border:0;border-radius:0;box-shadow:none}.form-panel{align-items:flex-start;padding:28px 24px 40px}.back-button{margin-bottom:24px}}
</style>



