<template>
  <div class="sitemap-page">
    <header class="page-hero">
      <div>
        <p class="eyebrow">FARM OPERATIONS</p>
        <h1>農場作業總覽</h1>
        <p class="subtitle">快速進入日常作業，掌握從引種到斷奶的完整生產流程。</p>
      </div>
      <div class="hero-mark" aria-hidden="true"><i class="fa fa-leaf"></i></div>
    </header>

    <section class="section-block" aria-labelledby="daily-title">
      <div class="section-heading">
        <div>
          <span class="section-kicker">DAILY TASKS</span>
          <h2 id="daily-title">常用作業</h2>
        </div>
        <span class="section-count">{{ visibleDailyCount }} 項功能</span>
      </div>

      <div class="operation-grid">
        <article v-for="group in dailyGroups" :key="group.title" class="operation-card">
          <div class="card-heading">
            <span class="card-icon" :class="group.tone"><i :class="group.icon"></i></span>
            <div><small>{{ group.english }}</small><h3>{{ group.title }}</h3></div>
          </div>
          <nav :aria-label="group.title + '功能'">
            <router-link
              v-for="item in visibleItems(group.items)"
              :key="item.name"
              :to="{ name: item.route }"
            >
              <span>{{ item.name }}</span><i class="fa fa-angle-right"></i>
            </router-link>
          </nav>
        </article>
      </div>
    </section>

    <section v-if="siteType != 2" class="section-block lifecycle" aria-labelledby="cycle-title">
      <div class="section-heading">
        <div>
          <span class="section-kicker">PRODUCTION CYCLE</span>
          <h2 id="cycle-title">生產週期</h2>
        </div>
        <span class="cycle-note"><i class="fa fa-refresh"></i> 五階段作業流程</span>
      </div>

      <div class="cycle-track" aria-hidden="true"><span></span></div>
      <div class="cycle-grid">
        <article v-for="(stage, index) in lifecycleStages" :key="stage.title" class="cycle-card">
          <div class="stage-top">
            <span class="stage-number">{{ ('0' + (index + 1)).slice(-2) }}</span>
            <span class="stage-icon"><i :class="stage.icon"></i></span>
          </div>
          <div class="stage-title"><small>{{ stage.english }}</small><h3>{{ stage.title }}</h3></div>
          <router-link v-for="item in stage.items" :key="item.name" :to="{ name: item.route }">
            {{ item.name }}<i class="fa fa-arrow-right"></i>
          </router-link>
        </article>
      </div>
    </section>

    <footer class="page-tip">
      <i class="fa fa-info-circle"></i>
      <span>功能項目會依您的場別與帳號權限顯示。</span>
    </footer>
  </div>
</template>

<script>
export default {
  name: 'SiteMap',
  data() {
    return {
      siteType: this.$store.getters.userProfile.SiteType,
      dailyGroups: [
        {
          title: '豬隻', english: 'HERD', icon: 'fa fa-tags', tone: 'sage',
          items: [
            { name: '種母豬', route: 'MA010301', breeding: true },
            { name: '種公豬', route: 'MA010302', breeding: true },
            { name: '商品豬', route: 'MA010303' }
          ]
        },
        {
          title: '移欄', english: 'MOVEMENT', icon: 'fa fa-exchange', tone: 'blue',
          items: [
            { name: '個體移欄', route: 'MA040302' },
            { name: '群體移出', route: 'MA040303' },
            { name: '群體移入', route: 'MA040304' },
            { name: '死淘作業', route: 'MA040301' }
          ]
        },
        {
          title: '動保', english: 'HEALTH', icon: 'fa fa-shield', tone: 'rose',
          items: [
            { name: '消毒作業', route: 'MA060302' },
            { name: '防疫作業', route: 'MA060203' },
            { name: '個體診斷', route: 'MA060104' },
            { name: '群體診斷', route: 'MA060106' }
          ]
        },
        {
          title: '餵飼', english: 'FEEDING', icon: 'fa fa-tint', tone: 'amber',
          items: [
            { name: '個體餵飼', route: 'MA050103' },
            { name: '群體餵飼', route: 'MA050102' },
            { name: '餵飼計畫', route: 'MA050101' }
          ]
        },
        {
          title: '體況', english: 'CONDITION', icon: 'fa fa-line-chart', tone: 'purple',
          items: [
            { name: '秤重作業', route: 'MA040210' },
            { name: '背脂量測', route: 'MA040211' },
            { name: '膘情作業', route: 'MA040212' }
          ]
        }
      ],
      lifecycleStages: [
        {
          title: '引種', english: 'INTRODUCTION', icon: 'fa fa-sign-in',
          items: [{ name: '耳標補發', route: 'MA010101' }, { name: '豬隻引種', route: 'MA010304' }]
        },
        {
          title: '配種', english: 'BREEDING', icon: 'fa fa-venus-mars',
          items: [
            { name: '查情作業', route: 'MA040201' }, { name: '採精作業', route: 'MA040202' },
            { name: '精液檢驗', route: 'MA040203' }, { name: '混精作業', route: 'MA040204' },
            { name: '輸精作業', route: 'MA040205' }
          ]
        },
        {
          title: '妊娠', english: 'GESTATION', icon: 'fa fa-heartbeat',
          items: [{ name: '妊檢作業', route: 'MA040206' }, { name: '流產作業', route: 'MA040207' }]
        },
        {
          title: '分娩', english: 'FARROWING', icon: 'fa fa-star',
          items: [{ name: '分娩作業', route: 'MA040208' }]
        },
        {
          title: '斷奶', english: 'WEANING', icon: 'fa fa-flag-checkered',
          items: [{ name: '斷奶作業', route: 'MA040209' }]
        }
      ]
    }
  },
  computed: {
    visibleDailyCount() {
      return this.dailyGroups.reduce((total, group) => total + this.visibleItems(group.items).length, 0)
    }
  },
  methods: {
    visibleItems(items) {
      if (this.siteType == 2) return items.filter(item => !item.breeding)
      return items
    }
  }
}
</script>

<style scoped>
.sitemap-page,.sitemap-page *{box-sizing:border-box}.sitemap-page{--forest:#173f35;--green:#2d715c;--lime:#b9d96b;--ink:#17221f;padding:8px 4px 34px;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans TC",sans-serif}.page-hero{position:relative;display:flex;align-items:center;justify-content:space-between;min-height:180px;padding:35px 40px;overflow:hidden;border-radius:20px;color:#fff;background:linear-gradient(125deg,#173f35,#28624f);box-shadow:0 14px 35px rgba(23,63,53,.15)}.page-hero:after{content:'';position:absolute;width:260px;height:260px;right:-90px;top:-95px;border:48px solid rgba(185,217,107,.09);border-radius:50%}.eyebrow{margin:0 0 9px;color:var(--lime);font-size:11px;font-weight:700;letter-spacing:.16em}.page-hero h1{margin:0 0 10px;font-size:30px;letter-spacing:-.03em}.subtitle{margin:0;color:rgba(255,255,255,.7);font-size:14px}.hero-mark{position:relative;z-index:1;display:grid;place-items:center;width:66px;height:66px;margin-right:12px;border-radius:20px;color:var(--forest);background:var(--lime);font-size:27px;transform:rotate(-4deg)}.section-block{margin-top:30px}.section-heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:15px;padding:0 3px}.section-kicker{display:block;margin-bottom:3px;color:#789087;font-size:9px;font-weight:700;letter-spacing:.14em}.section-heading h2{margin:0;font-size:21px;letter-spacing:-.02em}.section-count,.cycle-note{padding:6px 10px;border-radius:20px;color:#587168;background:#edf4f0;font-size:10px;font-weight:600}.cycle-note i{margin-right:5px}.operation-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px}.operation-card{overflow:hidden;border:1px solid #e4ebe7;border-radius:16px;background:#fff;box-shadow:0 6px 20px rgba(28,57,48,.05);transition:.2s}.operation-card:hover{transform:translateY(-2px);box-shadow:0 12px 28px rgba(28,57,48,.09)}.card-heading{display:flex;align-items:center;gap:11px;padding:17px 16px 13px}.card-icon{display:grid;place-items:center;flex:0 0 38px;height:38px;border-radius:11px;font-size:15px}.card-icon.sage{color:#35715e;background:#e7f1ec}.card-icon.blue{color:#41728b;background:#e8f1f5}.card-icon.rose{color:#a05c5a;background:#f7e9e7}.card-icon.amber{color:#97702d;background:#f8f0dc}.card-icon.purple{color:#745f8f;background:#f0eaf6}.card-heading small{display:block;color:#9ba7a2;font-size:8px;font-weight:700;letter-spacing:.11em}.card-heading h3{margin:2px 0 0;font-size:16px}.operation-card nav{padding:0 8px 9px}.operation-card nav a{display:flex;align-items:center;justify-content:space-between;min-height:37px;padding:0 9px;border-top:1px solid #f0f3f1;color:#4f605a;font-size:12px;text-decoration:none;transition:.18s}.operation-card nav a:hover{padding-left:13px;border-radius:7px;color:var(--green);background:#f2f7f4}.operation-card nav a i{color:#a5b1ad;font-size:11px}.lifecycle{position:relative}.cycle-track{position:absolute;top:74px;left:8%;right:8%;height:2px;background:#dce7e1}.cycle-track span{display:block;width:100%;height:100%;background:linear-gradient(90deg,var(--green),var(--lime))}.cycle-grid{position:relative;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px}.cycle-card{position:relative;min-height:230px;padding:17px 16px;border:1px solid #e4ebe7;border-radius:16px;background:#fff;box-shadow:0 6px 20px rgba(28,57,48,.05)}.stage-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:17px}.stage-number{color:#9aa9a3;font:700 10px ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.08em}.stage-icon{display:grid;place-items:center;width:35px;height:35px;border:4px solid #fff;border-radius:50%;color:#fff;background:var(--green);box-shadow:0 0 0 2px #dbe9e2;font-size:12px}.stage-title{margin-bottom:12px}.stage-title small{display:block;color:#91a09a;font-size:8px;font-weight:700;letter-spacing:.1em}.stage-title h3{margin:3px 0 0;font-size:17px}.cycle-card>a{display:flex;align-items:center;justify-content:space-between;margin-top:7px;padding:8px 9px;border-radius:8px;color:#52645d;background:#f6f8f7;font-size:11px;text-decoration:none;transition:.18s}.cycle-card>a:hover{color:#fff;background:var(--green)}.cycle-card>a i{font-size:9px}.page-tip{display:flex;align-items:center;gap:8px;margin-top:20px;padding:12px 14px;border:1px solid #e4ebe7;border-radius:11px;color:#788780;background:#fafcfb;font-size:11px}.page-tip i{color:var(--green)}
@media(max-width:1100px){.operation-grid,.cycle-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.cycle-track{display:none}}
@media(max-width:760px){.sitemap-page{padding-top:0}.page-hero{min-height:160px;padding:28px 25px}.page-hero h1{font-size:25px}.subtitle{max-width:310px;line-height:1.65}.hero-mark{display:none}.operation-grid,.cycle-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:480px){.page-hero{border-radius:15px}.section-heading{align-items:center}.operation-grid,.cycle-grid{grid-template-columns:1fr}.cycle-card{min-height:auto}.section-count,.cycle-note{display:none}}
</style>



